sys_lc_semantic_temporal_endpoint.script:
if(storage.sys_lc_systems_config?.clock?.enabled===false){skip=true;}else{
 const tick=Number(check({type:'game-tick'})||0),A=Object.assign({semanticEndpointsEnabled:true,defaultBedtimeHour:22,defaultBedtimeMinute:0,maxSemanticEndpointMinutes:10080},storage.sys_continuity_config?.activities??{});
 if(A.semanticEndpointsEnabled===false||Number(storage.sys_lc_time_claim_tick??-1)===tick){skip=true;}else{
  const raw=check({type:'action-text'})||[],text=(Array.isArray(raw)?raw:[raw]).map(x=>String(x||'')).join(' ').toLowerCase();
  const exact=/\b(?:for\s+)?(?:\d+(?:\.\d+)?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|half|an?|a)\s*(?:minutes?|mins?|hours?|hrs?|days?|weeks?)\b/i.test(text);
  if(/^\s*:/.test(text)||exact||/\b(?:sleep|nap)\b/.test(text)){skip=true;}else{
   const cal=Object.assign({startHour:12,startMinute:0},storage.sys_continuity_config?.calendar??{}),rest=Object.assign({defaultWakeHour:7,defaultWakeMinute:0},storage.sys_continuity_config?.rest??{});
   const start=Number(cal.startHour??12)*60+Number(cal.startMinute??0),abs=start+Number(storage.sys_clock_absolute_minutes??0),now=((abs%1440)+1440)%1440;
   let target=null,forceNextDay=false,label='';
   let m=text.match(/\buntil\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/i);
   if(m){let h=Number(m[1])%12;if(m[3].toLowerCase()==='pm')h+=12;target=h*60+Math.min(59,Number(m[2]||0));label='stated clock time';}
   else if(/\buntil\b[^.]{0,60}\b(?:tomorrow|the\s+next\s+day|next\s+day)\b[^.]{0,30}\b(?:morning|dawn|daybreak)\b/.test(text)){forceNextDay=true;target=Number(rest.defaultWakeHour??7)*60+Number(rest.defaultWakeMinute??0);label='next morning';}
   else if(/\buntil\b[^.]{0,60}\b(?:the\s+)?(?:next\s+day|tomorrow)\b/.test(text)){forceNextDay=true;target=now;label='next day';}
   else if(/\buntil\b[^.]{0,50}\b(?:morning|dawn|daybreak)\b/.test(text)){target=Number(rest.defaultWakeHour??7)*60+Number(rest.defaultWakeMinute??0);label='morning';}
   else if(/\buntil\b[^.]{0,70}\b(?:bedtime|it(?:'s| is)\s+time\s+to\s+(?:sleep|go\s+to\s+bed)|time\s+to\s+(?:sleep|go\s+to\s+bed)|go\s+to\s+bed)\b/.test(text)){target=Number(A.defaultBedtimeHour??22)*60+Number(A.defaultBedtimeMinute??0);label='bedtime';}
   else if(/\buntil\b[^.]{0,40}\bnoon\b/.test(text)){target=720;label='noon';}
   else if(/\buntil\b[^.]{0,40}\bmidnight\b/.test(text)){target=0;label='midnight';}
   else if(/\buntil\b[^.]{0,40}\bevening\b/.test(text)){target=18*60;label='evening';}
   else if(/\buntil\b[^.]{0,40}\b(?:night|nightfall)\b/.test(text)){target=21*60;label='night';}
   if(target===null){skip=true;}else{
    let advance=forceNextDay?(1440-now+target):(target-now);
    if(!forceNextDay&&advance<=0)advance+=1440;
    advance=Math.round(Math.max(1,Math.min(Number(A.maxSemanticEndpointMinutes??10080),advance)));
    storage.sys_clock_absolute_minutes=Number(storage.sys_clock_absolute_minutes??0)+advance;
    storage.sys_lc_time_claim_tick=tick;storage.sys_lc_last_time_advance_minutes=advance;storage.sys_lc_last_time_advance_reason='semantic-endpoint:'+label;
    const total=start+Number(storage.sys_clock_absolute_minutes??0),mod=((total%1440)+1440)%1440,h=Math.floor(mod/60),mi=mod%60;
    storage.sys_clock_hour=h;storage.sys_clock_minute=mi;storage.sys_clock_period=h<6?'night':h<12?'morning':h<18?'afternoon':'evening';
    effects.push({type:'story',instruction:'Living Continuity resolved the player\'s temporal endpoint "'+label+'": '+advance+' fictional minute(s) pass before this scene continues. The canonical clock already includes that passage. Do not add a generic or long-activity increment. Treat crossed day/date/schedule boundaries as real, but do not invent attendance, completed obligations, or unrelated major events.'});
   }
  }
 }
}

sys_lc_previous_prose_time_reconcile.script:
if(storage.sys_lc_systems_config?.clock?.enabled===false){skip=true;}else{
 const tick=Number(check({type:'game-tick'})||0),A=Object.assign({previousProseReconciliationEnabled:true,unspecifiedHoursMinutes:120,proseFallbackMinutes:60,maxProseReconcileMinutes:10080,defaultBedtimeHour:22,defaultBedtimeMinute:0},storage.sys_continuity_config?.activities??{});
 const ar=check({type:'action-text'})||[],action=String(Array.isArray(ar)?(ar.slice(-1)[0]||''):ar).trim();
 if(A.previousProseReconciliationEnabled===false||/^\s*:/.test(action)){skip=true;}else{
  const story=String(check({type:'story-text'})||'').toLowerCase();
  if(!story){skip=true;}else{
   const words={one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12,a:1,an:1};
   let inferred=0,label='',m=story.match(/\b(\d+(?:\.\d+)?)\s*(minutes?|mins?|hours?|hrs?|days?|weeks?)\s+(?:later|afterward|afterwards|pass(?:ed)?|have\s+passed)\b/i);
   if(m){const n=Number(m[1]),u=m[2];inferred=n*(u.startsWith('week')?10080:u.startsWith('day')?1440:u.startsWith('hour')||u.startsWith('hr')?60:1);label='previous prose explicit duration';}
   if(!inferred){m=story.match(/\b(one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|an?|a)\s+(minutes?|hours?|days?|weeks?)\s+(?:later|afterward|afterwards|pass(?:ed)?|have\s+passed)\b/i);if(m){const n=words[m[1]]||0,u=m[2];inferred=n*(u.startsWith('week')?10080:u.startsWith('day')?1440:u.startsWith('hour')?60:1);label='previous prose explicit duration';}}
   const cal=Object.assign({startHour:12,startMinute:0,minutesPerTurn:1},storage.sys_continuity_config?.calendar??{}),rest=Object.assign({defaultWakeHour:7,defaultWakeMinute:0},storage.sys_continuity_config?.rest??{});
   const start=Number(cal.startHour??12)*60+Number(cal.startMinute??0),abs=start+Number(storage.sys_clock_absolute_minutes??0),now=((abs%1440)+1440)%1440;
   let endpoint=null,forceNextDay=false;
   if(!inferred){
    if(/\b(?:the\s+)?(?:next|following)\s+(?:morning|dawn|daybreak)\b/.test(story)){forceNextDay=true;endpoint=Number(rest.defaultWakeHour??7)*60+Number(rest.defaultWakeMinute??0);label='previous prose next morning';}
    else if(/\b(?:the\s+)?(?:next|following)\s+day\b/.test(story)){forceNextDay=true;endpoint=now;label='previous prose next day';}
    else if(/\b(?:by|until|when)\s+(?:morning|dawn|daybreak)\b/.test(story)){endpoint=Number(rest.defaultWakeHour??7)*60+Number(rest.defaultWakeMinute??0);label='previous prose morning';}
    else if(/\b(?:by|until|when)\s+noon\b/.test(story)){endpoint=720;label='previous prose noon';}
    else if(/\b(?:by|until|when)\s+(?:evening|nightfall)\b/.test(story)){endpoint=18*60;label='previous prose evening';}
    else if(/\b(?:by|until|when)\s+(?:night|bedtime)\b/.test(story)){endpoint=Number(A.defaultBedtimeHour??22)*60+Number(A.defaultBedtimeMinute??0);label='previous prose night';}
    else if(/\b(?:hours\s+(?:later|pass)|several\s+hours\s+(?:later|pass)|hours\s+have\s+passed)\b/.test(story)){inferred=Math.max(1,Number(A.unspecifiedHoursMinutes??120));label='previous prose unspecified hours';}
    else if(/\b(?:some\s+time\s+later|much\s+later|after\s+a\s+while)\b/.test(story)){inferred=Math.max(1,Number(A.proseFallbackMinutes??60));label='previous prose elapsed time';}
    else {inferred=Math.max(1,Number(A.proseFallbackMinutes??60));label='previous prose model-confirmed elapsed time';}
   }
   const priorClaim=Number(storage.sys_lc_time_claim_tick??-999)===tick-1;
   const accounted=Math.max(0,priorClaim?Number(storage.sys_lc_last_time_advance_minutes??0):Number(cal.minutesPerTurn??1));
   let add=0;
   if(inferred>0)add=Math.max(0,inferred-accounted);
   else if(endpoint!==null){
    let needed=forceNextDay?(1440-now+endpoint):(endpoint-now);
    if(!forceNextDay&&needed<0)needed+=1440;
    if(!forceNextDay&&needed===0)needed=0;
    add=Math.max(0,needed);
   }
   add=Math.round(Math.min(Math.max(1,Number(A.maxProseReconcileMinutes??10080)),Math.max(0,add)));
   storage.sys_lc_last_prose_reconcile_tick=tick;
   if(add<=0){skip=true;}else{
    storage.sys_clock_absolute_minutes=Number(storage.sys_clock_absolute_minutes??0)+add;storage.sys_lc_last_prose_reconcile_minutes=add;storage.sys_lc_last_prose_reconcile_reason=label;
    const total=start+Number(storage.sys_clock_absolute_minutes??0),mod=((total%1440)+1440)%1440,h=Math.floor(mod/60),mi=mod%60;
    storage.sys_clock_hour=h;storage.sys_clock_minute=mi;storage.sys_clock_period=h<6?'night':h<12?'morning':h<18?'afternoon':'evening';
    effects.push({type:'story',instruction:'Living Continuity reconciled '+add+' previously untracked fictional minute(s) because the immediately preceding narration established real elapsed time ('+label+'). The canonical clock is corrected before resolving the current action. Do not narrate this as a new time skip; it already happened in the prior prose.'});
   }
  }
 }
}

