sys_clock_advance.script:
if(storage.sys_lc_systems_config?.clock?.enabled===false||storage.sys_lc_command_only_turn===true){
  skip=true;
}else{
  const tick=Number(check({type:'game-tick'})||0);
  if(Number(storage.sys_lc_time_claim_tick??-1)===tick){
    skip=true;
  }else{
    const raw=check({type:'action-text'})||[],fallback=String(Array.isArray(raw)?(raw.slice(-1)[0]||''):raw).trim(),text=storage.sys_lc_command_intersection_active===true?String(storage.sys_lc_command_effective_action??'').trim():fallback;
    if(/^\s*:/.test(text)){
      skip=true;
    }else{
      const cfg=Object.assign({startHour:12,startMinute:0,minutesPerTurn:1},storage.sys_continuity_config?.calendar??{});
      const advance=Math.max(0,Number(cfg.minutesPerTurn??1));
      storage.sys_clock_absolute_minutes=Number(storage.sys_clock_absolute_minutes??0)+advance;
      storage.sys_lc_last_time_advance_minutes=advance;
      storage.sys_lc_last_time_advance_reason='ordinary-turn';
      const total=Number(cfg.startHour??12)*60+Number(cfg.startMinute??0)+Number(storage.sys_clock_absolute_minutes??0);
      const mod=((total%1440)+1440)%1440,h=Math.floor(mod/60),mi=mod%60;
      storage.sys_clock_hour=h;storage.sys_clock_minute=mi;
      const now=h<6?'night':h<12?'morning':h<18?'afternoon':'evening';
      const prev=storage.sys_clock_period??'';storage.sys_clock_period=now;
      if(now!==prev)effects.push({type:'story',instruction:'Tracked time has entered '+now+'. Reflect the change only where relevant: lighting, routines, open businesses, fatigue, traffic, and NPC availability.'});
      else skip=true;
    }
  }
}

sys_date_command.script:
const defaults = {
  calendarName: 'Gregorian',
  startYear: 1,
  startMonth: 1,
  startDay: 1,
  startHour: 12,
  startMinute: 0,
  monthNames: ['January','February','March','April','May','June','July','August','September','October','November','December'],
  monthLengths: [31,28,31,30,31,30,31,31,30,31,30,31],
  leapRule: 'gregorian',
  leapMonth: 2,
  weekdayNames: ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'],
  startWeekdayIndex: 1,
  seasons: [
    { name: 'winter', months: [12,1,2] },
    { name: 'spring', months: [3,4,5] },
    { name: 'summer', months: [6,7,8] },
    { name: 'autumn', months: [9,10,11] }
  ],
  showWeekday: true,
  showSeason: true,
  yearLabel: '',
  dateFormat: 'month-day-year'
};

const cfg = Object.assign({}, defaults, storage.sys_continuity_config?.calendar ?? {});
const monthNames = Array.isArray(cfg.monthNames) && cfg.monthNames.length ? cfg.monthNames : defaults.monthNames;
const monthLengths = Array.isArray(cfg.monthLengths) && cfg.monthLengths.length ? cfg.monthLengths : defaults.monthLengths;
const monthCount = Math.min(monthNames.length, monthLengths.length);

const isLeap = (yr) => {
  if (cfg.leapRule === 'gregorian') return (yr % 4 === 0 && yr % 100 !== 0) || (yr % 400 === 0);
  return false;
};

const daysInMonth = (yr, month) => {
  let n = Number(monthLengths[month - 1] ?? 30);
  if (isLeap(yr) && month === Number(cfg.leapMonth ?? 2)) n += 1;
  return n;
};

const startMinute = Number(cfg.startHour ?? 12) * 60 + Number(cfg.startMinute ?? 0);
const elapsed = Number(storage.sys_clock_absolute_minutes ?? 0);
const dayOffset = Math.floor((startMinute + elapsed) / 1440);

let y = Number(cfg.startYear ?? 1);
let mo = Math.max(1, Math.min(monthCount, Number(cfg.startMonth ?? 1)));
let d = Math.max(1, Number(cfg.startDay ?? 1));
let add = dayOffset;

while (add > 0) {
  const left = daysInMonth(y, mo) - d;
  if (add <= left) {
    d += add;
    add = 0;
  } else {
    add -= left + 1;
    d = 1;
    mo += 1;
    if (mo > monthCount) {
      mo = 1;
      y += 1;
    }
  }
}

const weekdayNames = Array.isArray(cfg.weekdayNames) ? cfg.weekdayNames : defaults.weekdayNames;
let weekday = '';
if (weekdayNames.length) {
  const wi = ((Number(cfg.startWeekdayIndex ?? 0) + dayOffset) % weekdayNames.length + weekdayNames.length) % weekdayNames.length;
  weekday = weekdayNames[wi];
}

let season = '';
if (Array.isArray(cfg.seasons)) {
  for (const s of cfg.seasons) {
    if (s && Array.isArray(s.months) && s.months.includes(mo)) {
      season = String(s.name ?? '');
      break;
    }
  }
}

const monthName = String(monthNames[mo - 1] ?? ('Month ' + mo));
const yearText = (cfg.yearLabel ? String(cfg.yearLabel) + ' ' : '') + String(y);

let dateText = '';
if (cfg.dateFormat === 'day-month-year') dateText = d + ' ' + monthName + ' ' + yearText;
else if (cfg.dateFormat === 'year-month-day') dateText = yearText + ', ' + monthName + ' ' + d;
else dateText = monthName + ' ' + d + ', ' + yearText;

if (cfg.showWeekday !== false && weekday) dateText = weekday + ', ' + dateText;
if (cfg.showSeason !== false && season) dateText += ' (' + season + ')';

effects.push({
  type: 'story',
  instruction: 'System date request. Report the tracked ' + String(cfg.calendarName ?? 'calendar') + ' date as ' + dateText + ' concisely, without advancing the fiction or treating the command as spoken dialogue.'
});

sys_weather_prompt.script:
const __lcTick=Number(check({type:'game-tick'})||0),__lcMod=storage.sys_lc_moderator_state??{};if(__lcMod.freezeLcProgressOnBlockedAction!==false&&Number(storage.sys_lc_action_suppressed_tick)===__lcTick){skip=true;}else{if(storage.sys_lc_systems_config?.weather?.enabled===false){skip=true;}else{const base={enabled:true,checkpointTicks:15,simulationStepMinutes:60,narrationCheckpointMinutes:180,allowSevereWeather:true,preserveEstablishedWeather:true,temperatureUnit:'C',baseTemperatureC:{winter:3,spring:13,summer:24,autumn:14},diurnalRangeC:8,humidityBaseline:60,prevailingWindKph:14,storminess:.35,volatility:.45,regionalProfiles:{}};
const cfg=Object.assign({},base,storage.sys_continuity_config?.weather??{});
if(cfg.enabled===false){skip=true;}else{
 const now=Number(storage.sys_clock_absolute_minutes??0),step=Math.max(15,Number(cfg.simulationStepMinutes??cfg.checkpointTicks??60)),last=Number(storage.sys_weather_last_update_minute??-1);
 if(last>=0&&(now-last)<step){skip=true;}else{
  const cal=Object.assign({startMonth:1,startDay:1,startHour:12,startMinute:0,monthLengths:[31,28,31,30,31,30,31,31,30,31,30,31],seasons:[{name:'winter',months:[12,1,2]},{name:'spring',months:[3,4,5]},{name:'summer',months:[6,7,8]},{name:'autumn',months:[9,10,11]}]},storage.sys_continuity_config?.calendar??{});
  const start=Number(cal.startHour??12)*60+Number(cal.startMinute??0),total=start+now,minute=((total%1440)+1440)%1440,hour=minute/60;
  let days=Math.floor(total/1440),mo=Math.max(1,Number(cal.startMonth??1)),d=Math.max(1,Number(cal.startDay??1)),ml=Array.isArray(cal.monthLengths)&&cal.monthLengths.length?cal.monthLengths:[31,28,31,30,31,30,31,31,30,31,30,31];
  while(days>0){const left=Number(ml[mo-1]??30)-d;if(days<=left){d+=days;days=0;}else{days-=left+1;d=1;mo++;if(mo>ml.length)mo=1;}}
  let season='temperate';for(const s of (Array.isArray(cal.seasons)?cal.seasons:[])){if(s&&Array.isArray(s.months)&&s.months.includes(mo)){season=String(s.name??'temperate').toLowerCase();break;}}
  const region=String(check({type:'party-region'})||''),rp=(cfg.regionalProfiles&&typeof cfg.regionalProfiles==='object'&&cfg.regionalProfiles[region])||{},c=Object.assign({},cfg,rp);
  const seedBase=Math.floor(now/step)+mo*97+d*13+region.length*31;
  const rnd=(salt)=>{const x=Math.sin((seedBase+salt)*12.9898)*43758.5453;return x-Math.floor(x);};
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v)),prev=(storage.sys_weather_state&&typeof storage.sys_weather_state==='object')?storage.sys_weather_state:null;
  const temps=(c.baseTemperatureC&&typeof c.baseTemperatureC==='object')?c.baseTemperatureC:base.baseTemperatureC,seasonBase=Number(temps[season]??c.meanTemperatureC??14);
  const diurnal=-Math.cos((hour-5)/24*Math.PI*2)*Number(c.diurnalRangeC??8)/2;
  const vol=clamp(Number(c.volatility??.45),0,1),storminess=clamp(Number(c.storminess??.35),0,1);
  const pressureTarget=1015+(rnd(2)-.5)*18-(rnd(3)<storminess?8:0),pressure=clamp(prev?Number(prev.pressureHpa)*.72+pressureTarget*.28:pressureTarget,970,1040);
  const pressureTrend=prev?pressure-Number(prev.pressureHpa??pressure):0;
  let humidity=clamp((prev?Number(prev.humidityPct)*.65:Number(c.humidityBaseline??60)*.65)+Number(c.humidityBaseline??60)*.35+(rnd(4)-.5)*18*vol,20,100);
  const cloudTarget=clamp((humidity-35)*1.25+(1015-pressure)*2.0+(rnd(5)-.5)*25,0,100),cloud=clamp(prev?Number(prev.cloudPct)*.6+cloudTarget*.4:cloudTarget,0,100);
  let wind=clamp(Number(c.prevailingWindKph??14)*(0.55+rnd(6)*.9)+(1012-pressure)*.9,0,100);
  const dirs=['N','NE','E','SE','S','SW','W','NW'],windDirection=dirs[Math.floor(rnd(7)*dirs.length)%dirs.length];
  let precipIntensity='none',precipType='none';
  const precipChance=clamp((humidity-55)/55+(cloud-55)/80+(1012-pressure)/45,0,.95);
  const pr=rnd(8);
  if(pr<precipChance){const intensityScore=precipChance+rnd(9)*.45;precipIntensity=intensityScore>1.12?'heavy':intensityScore>.82?'moderate':'light';}
  let temp=seasonBase+diurnal+(rnd(10)-.5)*5*vol;
  if(prev)temp=Number(prev.temperatureC)*.35+temp*.65;
  temp=Math.round(temp*10)/10;
  if(precipIntensity!=='none')precipType=temp<=0?'snow':temp<=2&&rnd(11)<.45?'sleet':'rain';
  let severity='none';
  if(cfg.allowSevereWeather!==false){
   const severeScore=storminess*(1010-pressure)/25+(wind/100)+((precipIntensity==='heavy')?.35:0)+rnd(12)*.35;
   if(severeScore>1.55)severity='severe';else if(severeScore>1.15)severity='hazardous';
  }
  if(severity==='severe'){wind=Math.max(wind,55);precipIntensity=precipIntensity==='none'?'heavy':precipIntensity;if(precipType==='none')precipType=temp<=1?'snow':'rain';}
  const visibility=clamp(30-cloud*.16-(precipIntensity==='light'?4:precipIntensity==='moderate'?10:precipIntensity==='heavy'?18:0)-wind*.04,0.3,30);
  const feels=temp-(wind>20?Math.min(10,(wind-20)*.08):0)+(temp>24?Math.max(0,(humidity-60)*.04):0);
  let condition='clear';if(precipType!=='none')condition=(precipIntensity==='heavy'?'heavy ':'')+precipType;else if(cloud>80)condition='overcast';else if(cloud>50)condition='mostly cloudy';else if(cloud>25)condition='partly cloudy';
  const front=pressureTrend<-1.8?'approaching low pressure':pressureTrend>1.8?'clearing high pressure':'stable pressure';
  const makeForecast=(hrs,salt)=>{const h=(hour+hrs)%24,di=-Math.cos((h-5)/24*Math.PI*2)*Number(c.diurnalRangeC??8)/2,t=Math.round((seasonBase+di+(rnd(salt)-.5)*5*vol)*10)/10,pc=clamp(precipChance+(rnd(salt+1)-.5)*.35,0,.95);return{hoursAhead:hrs,temperatureC:t,precipChancePct:Math.round(pc*100),windKph:Math.round(clamp(Number(c.prevailingWindKph??14)*(0.6+rnd(salt+2)),0,90)),summary:pc>.65?(t<=1?'snow likely':'rain likely'):pc>.35?'possible precipitation':(cloud>65?'cloudy':'fair')};};
  const state={generatedAtMinute:now,region,season,condition,temperatureC:temp,feelsLikeC:Math.round(feels*10)/10,humidityPct:Math.round(humidity),pressureHpa:Math.round(pressure),pressureTrendHpa:Math.round(pressureTrend*10)/10,cloudPct:Math.round(cloud),windKph:Math.round(wind),windDirection,precipType,precipIntensity,visibilityKm:Math.round(visibility*10)/10,severity,front,forecast:[makeForecast(6,30),makeForecast(12,40),makeForecast(24,50)]};
  storage.sys_weather_state=state;storage.sys_weather_last_update_minute=now;
  const narrEvery=Math.max(step,Number(c.narrationCheckpointMinutes??180)),lastNarr=Number(storage.sys_weather_last_prompt_tick??-999999),changed=!prev||prev.condition!==condition||prev.severity!==severity||Math.abs(Number(prev.temperatureC??temp)-temp)>=5;
  if(changed||(now-lastNarr)>=narrEvery){
   storage.sys_weather_last_prompt_tick=now;
   let instruction='WEATHER STATE (authoritative continuity): '+condition+', '+temp+'°C (feels '+state.feelsLikeC+'°C), humidity '+state.humidityPct+'%, wind '+state.windDirection+' '+state.windKph+' km/h, visibility '+state.visibilityKm+' km, '+front+'.';
   if(precipType!=='none')instruction+=' Precipitation: '+precipIntensity+' '+precipType+'.';
   if(severity!=='none')instruction+=' Severity: '+severity+'. Reflect practical hazards where relevant.';
   instruction+=' Preserve this weather until a later weather-state update changes it. Mention it only when perceptible or consequential; do not force ambient weather exposition into every turn.';
   effects.push({type:'story',instruction});
  }else skip=true;
 }
}}}

sys_living_world_location_drift.script:
if(storage.sys_lc_systems_config?.locationDrift?.enabled===false){skip=true;}else{const cfg = Object.assign(
  {
    driftEnabled: true,
    minorChangeMinutes: 1440,
    moderateChangeMinutes: 10080,
    majorChangeMinutes: 43200
  },
  storage.sys_continuity_config?.locations ?? {}
);

if (cfg.driftEnabled === false) {
  skip = true;
} else {
  const current = String(check({type:'party-location'})||'');
  const now = Number(storage.sys_clock_absolute_minutes ?? 0);

  if (!storage.sys_living_departed_at) storage.sys_living_departed_at = {};
  const previous = String(storage.sys_living_last_location ?? '');

  if (previous && current && previous !== current) {
    storage.sys_living_departed_at[previous] = now;

    const departed = Number(storage.sys_living_departed_at[current] ?? now);
    const away = Math.max(0, now - departed);

    if (away >= Number(cfg.minorChangeMinutes ?? 1440)) {
      let scale = 'minor';
      if (away >= Number(cfg.majorChangeMinutes ?? 43200)) scale = 'substantial';
      else if (away >= Number(cfg.moderateChangeMinutes ?? 10080)) scale = 'moderate';

      effects.push({
        type: 'story',
        instruction:
          'The party has returned to a previously visited location after substantial fictional time away. Allow ' +
          scale +
          ' off-screen changes only where established NPC routines, projects, local conditions, consequences, or ongoing events plausibly support them. Do not invent major upheaval merely because time passed.'
      });
    }
  }

  if (current) storage.sys_living_last_location = current;
  if (!current) skip = true;
}}

sys_soft_arc_review.script:
if(storage.sys_lc_systems_config?.softArcs?.enabled===false){skip=true;}else{
 const cfg=Object.assign({softArcEnabled:true,reviewIntervalMinutes:35,maxDevelopmentsPerReview:1,interruptDowntime:false,allowNewThreads:false},storage.sys_continuity_config?.pacing??{}),M=storage.sys_continuity_config?.modernization??{};
 if(cfg.softArcEnabled===false){skip=true;}else{
  const now=Number(storage.sys_clock_absolute_minutes??0),last=Number(storage.sys_soft_arc_last_review_minute??0),interval=Math.max(1,Number(cfg.reviewIntervalMinutes??cfg.reviewIntervalTicks??35));
  if(now-last<interval){skip=true;}else{
