   if(M.useNarrativeDirectionForSoftArcs!==false&&storage.sys_lc_arc_intent){
    const A=storage.sys_lc_arc_intent;A.stale=true;A.regenerationRequestedAt=now;A.regenerationReason='legacy-soft-arc-review';
    A.legacySoftArcReview={at:now,since:last,maxDevelopments:Math.max(0,Number(cfg.maxDevelopmentsPerReview??1)),allowNewThreads:cfg.allowNewThreads===true,interruptDowntime:cfg.interruptDowntime===true};
    storage.sys_lc_soft_arc_context_pending={at:now,since:last,maxDevelopments:Math.max(0,Number(cfg.maxDevelopmentsPerReview??1)),allowNewThreads:cfg.allowNewThreads===true,interruptDowntime:cfg.interruptDowntime===true};
    skip=true;
   }else{
