sys_sleep_to_morning.script:
if(storage.sys_lc_systems_config?.clock?.enabled===false){
  skip=true;
}else{
  const cal=Object.assign({startHour:12,startMinute:0},storage.sys_continuity_config?.calendar??{});
  const rest=Object.assign({overnightSleepEnabled:true,defaultWakeHour:7,defaultWakeMinute:0},storage.sys_continuity_config?.rest??{});
  const raw=check({type:'action-text'})||[],text=(Array.isArray(raw)?raw:[raw]).map(x=>String(x||'')).join(' ');
  const exact=/\b(?:for\s+)?(?:\d+(?:\.\d+)?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|half|an?|a)\s*(?:minutes?|mins?|hours?|hrs?)\b/i.test(text);
  const tick=Number(check({type:'game-tick'})||0);
  if(rest.overnightSleepEnabled===false||exact||Number(storage.sys_lc_time_claim_tick??-1)===tick){
    skip=true;
  }else{
    const start=Number(cal.startHour??12)*60+Number(cal.startMinute??0);
    const total=start+Number(storage.sys_clock_absolute_minutes??0),mod=((total%1440)+1440)%1440;
    const target=Math.max(0,Math.min(1439,Number(rest.defaultWakeHour??7)*60+Number(rest.defaultWakeMinute??0)));
    let advance=(target-mod+1440)%1440;if(advance<240)advance+=1440;
    storage.sys_clock_absolute_minutes=Number(storage.sys_clock_absolute_minutes??0)+advance;
    storage.sys_lc_time_claim_tick=tick;storage.sys_lc_last_time_advance_minutes=advance;storage.sys_lc_last_time_advance_reason='sleep-until';
    storage.sys_clock_hour=Math.floor(target/60);storage.sys_clock_minute=target%60;
    const h=storage.sys_clock_hour;storage.sys_clock_period=h<6?'night':h<12?'morning':h<18?'afternoon':'evening';
    effects.push({type:'story',instruction:'Living Continuity advanced the clock by '+advance+' minute(s) for overnight sleep, to about '+String(storage.sys_clock_hour).padStart(2,'0')+':'+String(storage.sys_clock_minute).padStart(2,'0')+'. Do not invent an interruption merely because time passed.'});
  }
}

sys_long_activity_time_cost.script:
