  skip=true;
}else{
  const cfg=Object.assign({enabled:true,defaultLongActivityMinutes:60,minimumSubstantialActivityMinutes:15},storage.sys_continuity_config?.activities??{});
  const tick=Number(check({type:'game-tick'})||0),raw=check({type:'action-text'})||[],text=(Array.isArray(raw)?raw:[raw]).map(x=>String(x||'')).join(' ');
  const exact=/\b(?:\d+(?:\.\d+)?|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|half|an?|a)\s*(?:minutes?|mins?|hours?|hrs?|days?|weeks?)\b/i.test(text);
  if(cfg.enabled===false||exact||Number(storage.sys_lc_time_claim_tick??-1)===tick){
