sys_lc_quest_index_monitor.script:
if(storage.sys_lc_systems_config?.questIndex?.enabled===false){skip=true;}else{const tick=Number(check({type:'game-tick'})||0);
if(!storage.sys_continuity_config||typeof storage.sys_continuity_config!=='object')storage.sys_continuity_config={};
const d={enabled:true,scanIntervalTicks:20,maxQuestScan:250,maxSummaryQuests:30,includeAvailable:false};
storage.sys_continuity_config.quests=Object.assign({},d,storage.sys_continuity_config.quests||{});
const cfg=storage.sys_continuity_config.quests;
if(cfg.enabled===false){skip=true;}else{
 if(!storage.sys_quest_ledger||typeof storage.sys_quest_ledger!=='object')storage.sys_quest_ledger={version:1,registry:{},lastScanTick:-999,lastTriggerCount:-1,stats:{}};
 const L=storage.sys_quest_ledger;if(!L.registry)L.registry={};
 const Q=(id)=>{id=String(id||'');if(!id)return null;if(!L.registry[id])L.registry[id]={id,status:'unknown',objectives:{},prerequisites:[],chainNext:[],coverage:{}};return L.registry[id];};
 const O=(q,id)=>{id=String(id||'');if(!q||!id)return null;if(!q.objectives[id])q.objectives[id]={id,text:'',revealedBy:[],unlocks:[],completionTriggers:[],visibility:'unknown'};return q.objectives[id];};
 const keys=Object.keys(triggers||{});
 const interval=Math.max(1,Number(cfg.scanIntervalTicks||20));
 if(keys.length!==Number(L.lastTriggerCount??-1)||tick-Number(L.lastScanTick??-999)>=interval){
  L.registry={};let scriptedObjectiveTriggers=0,semanticObjectiveTriggers=0,objectiveLinks=0,chainLinks=0;
  for(const name of keys){
   if(name.indexOf('sys_lc_quest_')===0)continue;
   const tr=triggers[name]||{},cs=Array.isArray(tr.conditions)?tr.conditions:[],es=Array.isArray(tr.effects)?tr.effects:[];
   for(const c of cs){
    if(c&&c.type==='quest-status'&&c.questId)Q(c.questId);
    if(c&&c.type==='quests-completed'&&c.value)Q(c.value);
   }
   for(const e of es){
    if(e&&e.type==='quest-init'&&e.value)Q(e.value);
    if(e&&e.questId&&String(e.type||'').indexOf('quest-')===0)Q(e.questId);
   }
   const prereq=cs.filter(c=>c&&c.type==='quests-completed'&&c.operator==='contains'&&c.value).map(c=>String(c.value));
   const starts=es.filter(e=>e&&e.type==='quest-init'&&e.value).map(e=>String(e.value));
   for(const b of starts)for(const a of prereq){const qb=Q(b),qa=Q(a);if(qb.prerequisites.indexOf(a)<0)qb.prerequisites.push(a);if(qa.chainNext.indexOf(b)<0)qa.chainNext.push(b);chainLinks++;}
   const comps=es.filter(e=>e&&e.type==='quest-objective-complete'&&e.questId&&e.objectiveId);
   const revs=es.filter(e=>e&&e.type==='quest-objective-reveal'&&e.questId&&e.objectiveId);
   const nexts=es.filter(e=>e&&e.type==='quest-next-step-set'&&e.questId&&e.text);
   for(const e of comps){
    const q=Q(e.questId),o=O(q,e.objectiveId);o.completionTriggers.push(name);
    if(String(tr.script||'').trim())scriptedObjectiveTriggers++;
    if(cs.some(c=>c&&c.type==='story'))semanticObjectiveTriggers++;
   }
   for(const e of revs){const q=Q(e.questId),o=O(q,e.objectiveId);o.visibility='revealed-by-trigger';}
   for(const r of revs)for(const c of comps)if(String(r.questId)===String(c.questId)){
    const q=Q(r.questId),from=O(q,c.objectiveId),to=O(q,r.objectiveId);
    if(from.unlocks.indexOf(to.id)<0)from.unlocks.push(to.id);
    if(to.revealedBy.indexOf(from.id)<0)to.revealedBy.push(from.id);
    objectiveLinks++;
   }
   for(const n of nexts){
    const same=revs.filter(r=>String(r.questId)===String(n.questId));
    if(same.length===1){const o=O(Q(n.questId),same[0].objectiveId);if(!o.text)o.text=String(n.text);}
   }
  }
  L.lastScanTick=tick;L.lastTriggerCount=keys.length;L.stats={triggerCount:keys.length,questCount:Object.keys(L.registry).length,objectiveLinks,chainLinks,scriptedObjectiveTriggers,semanticObjectiveTriggers};
 }
 const ids=Object.keys(L.registry).slice(0,Math.max(1,Number(cfg.maxQuestScan||250)));
 for(const id of ids){
  const q=L.registry[id];q.status='unknown';
  for(const v of ['accepted','available','completed','abandoned','rejected','expired','hidden']){
   try{if(check({type:'quest-status',questId:id,operator:'equals',value:v})){q.status=v;break;}}catch(_){}
  }
  for(const o of Object.values(q.objectives||{})){
   if(q.status==='completed')o.runtimeState='completed-with-quest';
   else if(q.status!=='accepted')o.runtimeState='not-active';
   else if(!o.revealedBy.length)o.runtimeState='candidate-open';
   else o.runtimeState='unknown-native-state';
  }
 }
 skip=true;
}}

sys_lc_quest_summary_command.script:
if(storage.sys_lc_systems_config?.questIndex?.enabled===false){skip=true;}else{const cfg=(storage.sys_continuity_config&&storage.sys_continuity_config.quests)||{};
if(cfg.enabled===false){skip=true;}else{
 const L=storage.sys_quest_ledger||{registry:{},stats:{}},R=L.registry||{},cap=Math.max(1,Number(cfg.maxSummaryQuests||30));
 const live=Object.values(R).filter(q=>q.status==='accepted'||(cfg.includeAvailable===true&&q.status==='available')).sort((a,b)=>String(a.id).localeCompare(String(b.id)));
 const nice=s=>String(s||'').replace(/[_-]+/g,' ').replace(/\s+/g,' ').trim();
 let out='ACTIVE QUESTS';
 if(!live.length)out+='\nNo accepted quests were discovered through the host world’s quest wiring.';
 for(const q of live.slice(0,cap)){
  out+='\n\n• '+q.id;
  const done=(q.prerequisites||[]).filter(p=>R[p]&&R[p].status==='completed');
  if(done.length)out+='\n  Continues from: '+done.join(', ');
  const objs=Object.values(q.objectives||{});
  const roots=objs.filter(o=>o.runtimeState==='candidate-open');
  const unknown=objs.filter(o=>o.runtimeState==='unknown-native-state');
  if(roots.length){
   out+='\n  Candidate open objectives:';
   for(const o of roots)out+='\n   - '+(o.text||nice(o.id));
  }
  if(unknown.length)out+='\n  Additional authored objectives detected: '+unknown.map(o=>o.text||nice(o.id)).join('; ')+' (native reveal/completion state is not exposed to scripts).';
  if(!objs.length)out+='\n  Objective detail: unavailable from trigger wiring; native quest journal remains authoritative.';
 }
 const S=L.stats||{};
 out+='\n\nCoverage: '+Number(S.questCount||0)+' quest ID(s), '+Number(S.chainLinks||0)+' chain link(s), '+Number(S.objectiveLinks||0)+' objective dependency link(s) discovered.';
 if(Number(S.scriptedObjectiveTriggers||0)>0)out+='\nSome objective triggers contain custom scripts; Living Continuity does not reinterpret them.';
 out+='\nThis ledger never changes native quest state.';
 const chunks=[];for(let i=0;i<out.length;i+=900)chunks.push(out.slice(i,i+900));
 for(let i=0;i<Math.min(chunks.length,8);i++)effects.push({type:'story',instruction:'OUT-OF-WORLD LIVING CONTINUITY QUEST SUMMARY '+(i+1)+'/'+Math.min(chunks.length,8)+'. Present only the supplied status text. Do not advance the scene or invent quest facts:\n'+chunks[i]});
}}

sys_lc_quest_debug_command.script:
