const counts={};for(const q of Object.values(R)){const s=q.status||'unknown';counts[s]=(counts[s]||0)+1;}
const text='LIVING CONTINUITY QUEST INDEX DEBUG
Discovered quest IDs: '+Object.keys(R).length+'
Statuses: '+Object.keys(counts).sort().map(k=>k+'='+counts[k]).join(', ')+'
Host triggers scanned: '+Number(S.triggerCount||0)+'
Quest-chain links: '+Number(S.chainLinks||0)+'
Objective dependency links: '+Number(S.objectiveLinks||0)+'
Scripted objective triggers left uninterpreted: '+Number(S.scriptedObjectiveTriggers||0)+'
Semantic objective triggers indexed but not re-evaluated: '+Number(S.semanticObjectiveTriggers||0)+'.';
effects.push({type:'story',instruction:'OUT-OF-WORLD LIVING CONTINUITY DEBUG. Present exactly this diagnostic without advancing fiction:
'+text});}

sys_weather_command.script:
if(storage.sys_lc_systems_config?.weather?.enabled===false){skip=true;}else{const a=check({type:'action-text'})||[],cmd=String(Array.isArray(a)?(a.slice(-1)[0]||''):a).trim(),w=storage.sys_weather_state;
if(!w){effects.push({type:'story',instruction:'System weather request. No simulated weather state exists yet. Report that weather initializes on the next continuity weather update, without advancing the fiction.'});}
else{const unit=String(storage.sys_continuity_config?.weather?.temperatureUnit??'C').toUpperCase(),cv=(c)=>unit==='F'?Math.round((Number(c)*9/5+32)*10)/10:Number(c),sym=unit==='F'?'°F':'°C';
let text='System weather request. Report current tracked weather concisely and without treating this command as spoken dialogue: '+w.condition+', '+cv(w.temperatureC)+sym+' (feels '+cv(w.feelsLikeC)+sym+'), humidity '+w.humidityPct+'%, wind '+w.windDirection+' '+w.windKph+' km/h, visibility '+w.visibilityKm+' km, pressure '+w.pressureHpa+' hPa, '+w.front+(w.precipType!=='none'?'; '+w.precipIntensity+' '+w.precipType:'')+(w.severity!=='none'?'; '+w.severity+' conditions':'')+'.';
if(/\bforecast$/i.test(cmd)&&Array.isArray(w.forecast)){text+=' Also report this short forecast: '+w.forecast.map(f=>'+'+f.hoursAhead+'h '+cv(f.temperatureC)+sym+', '+f.precipChancePct+'% precip, '+f.windKph+' km/h wind, '+f.summary).join(' | ')+'.';}
effects.push({type:'story',instruction:text});}}

sys_lc_systems_initialize.script:
const C=storage.sys_continuity_config??{};
