 V.stats.jobs=Number(V.stats.jobs||0)+jobs;V.stats.upserts=Number(V.stats.upserts||0)+up;V.stats.deletes=Number(V.stats.deletes||0)+del;V.stats.snapshots=Number(V.stats.snapshots||0)+1;V.stats.dirtyCount=Object.keys(V.dirty).length;
