sys_lc_biology_initialize.script:
const sys=storage.sys_lc_systems_config?.biology,cfg=storage.sys_continuity_config?.biology;
if(sys?.enabled===false||cfg?.enabled===false){skip=true;}else{
 const isObj=x=>x&&typeof x==='object'&&!Array.isArray(x),clone=x=>JSON.parse(JSON.stringify(x));
 const D=storage.sys_lc_biology_definitions??(storage.sys_lc_biology_definitions={});
 const P=storage.sys_lc_biology_profiles??(storage.sys_lc_biology_profiles={});
 const defs=isObj(cfg?.definitions)?cfg.definitions:{},profiles=isObj(cfg?.individualProfiles)?cfg.individualProfiles:{};
 let changed=0;
 for(const [id,x] of Object.entries(defs))if(isObj(x)&&!D[id]){D[id]=clone(x);D[id].id=D[id].id??id;changed++;}
 for(const [id,x] of Object.entries(profiles))if(isObj(x)&&!P[id]){P[id]=clone(x);P[id].id=P[id].id??id;changed++;}
