}

sys_lc_biology_context.script:
if(storage.sys_lc_context_governor?.enabled===true&&storage.sys_lc_systems_config?.contextGovernor?.enabled!==false&&storage.sys_continuity_config?.contextGovernor?.enabled!==false){skip=true;}else{
const sys=storage.sys_lc_systems_config?.biology,cfg=storage.sys_continuity_config?.biology;
if(sys?.enabled===false||cfg?.enabled===false||cfg?.narratorRetrievalEnabled===false){skip=true;}else{
 const tick=Number(check({type:'game-tick'})||0),now=Number(storage.sys_clock_absolute_minutes??tick),
 last=Number(storage.sys_lc_biology_last_context_minute??-999999),every=Math.max(1,Number(cfg?.contextRefreshMinutes??60));
 const raw=check({type:'action-text'})||[],action=String(Array.isArray(raw)?raw.join(' '):raw).toLowerCase();
 const tags=new Set(['always','identity','visible']);
 const add=(tag,rx)=>{if(rx.test(action))tags.add(tag);};
 add('locomotion',/\b(fly|flight|walk|run|swim|climb|move|wing|tail|limb)\b/);
 add('medical',/\b(clinic|medical|doctor|nurse|examine|exam|injur|wound|ill|sick|health|anatom|physiol|diagnos|treat)\w*/);
 add('developmental',/\b(age|aging|grow|growth|hatch|juvenile|adolescent|development)\w*/);
 add('reproductive',/\b(reproduc|fertil|pregnan|gestat|breed|parentage|inherit|egg|ovipar|birth)\w*/);
 add('egg',/\b(egg|shell|hatch)\w*/);add('incubation',/\b(incubat|hatchery|pre-hatch)\w*/);
 add('grooming',/\b(groom|wash|bathe|shed|brush|clean)\w*/);
 add('feeding',/\b(eat|feed|diet|meal|nutrition|digest)\w*/);
 add('environmental',/\b(weather|heat|cold|water|vacuum|environment|habitat)\w*/);
 add('elemental',/\b(element|fire|ice|lightning|aether|magic|breath)\w*/);
 add('intimate',/\b(intimat|sex|genital|arousal|intercourse|sexual)\w*/);
 const deep=[...tags].some(x=>!['always','identity','visible'].includes(x));
 if(now-last<every&&!deep){skip=true;}else{
  const D=storage.sys_lc_biology_definitions??{},P=storage.sys_lc_biology_profiles??{},lines=[];
  const maxP=Math.max(1,Number(cfg?.maxContextProfiles??6)),maxC=Math.max(500,Number(cfg?.maxContextCharacters??4200));
  const compact=(x,allow)=>{
   const o={};
   for(const k of ['classification','features','phenotype','development','persistentChanges','currentCondition','transientPresentation']){
    if(x?.[k]!==undefined)o[k]=x[k];
   }
   if(allow&&x?.anatomy!==undefined)o.anatomy=x.anatomy;
   if(allow&&x?.physiology!==undefined)o.physiology=x.physiology;
   if((tags.has('reproductive')||tags.has('intimate')||tags.has('egg')||tags.has('incubation'))&&x?.reproduction!==undefined)o.reproduction=x.reproduction;
   if((tags.has('medical')||tags.has('developmental'))&&x?.biologicalBaseline!==undefined)o.biologicalBaseline=x.biologicalBaseline;
   if(x?.contextBlocks&&typeof x.contextBlocks==='object'){
    o.contextBlocks={};
    for(const [k,v] of Object.entries(x.contextBlocks))if(tags.has(k)||k==='always')o.contextBlocks[k]=v;
   }
   return o;
  };
  let n=0;
  for(const [id,p] of Object.entries(P)){
   if(n>=maxP||!p||typeof p!=='object'||p.narrate===false)continue;
   const defId=p.definitionId??p.classification?.definitionId,def=defId?D[defId]:null;
   const entry={id,definitionId:defId??null};
   if(def)entry.definition=compact(def,deep);entry.individual=compact(p,deep);
   let s='Biology '+id+': '+JSON.stringify(entry);
   if(lines.join('\n').length+s.length>maxC)break;lines.push(s);n++;
  }
  if(!lines.length){skip=true;}else{
   storage.sys_lc_biology_last_context_minute=now;
   const head='BIOLOGICAL CONTINUITY (authoritative host-defined facts). Missing fields are unknown, not false. Species definition supplies defaults; individual profile overrides it. Preserve persistent phenotype and acquired changes. Use only scene-relevant facts; do not infer personality, consent, sexuality, social role, or unregistered anatomy. Context tags: '+[...tags].join(', ')+'.\n';
   const text=head+lines.join('\n');for(let i=0;i<text.length&&effects.length<8;i+=850)effects.push({type:'story',instruction:text.slice(i,i+850)});
  }
 }
}
}

sys_lc_biology_command.script:
const raw=check({type:'action-text'})||[],cmd=String(Array.isArray(raw)?(raw.slice(-1)[0]||''):raw).trim(),m=cmd.match(/^:lc\s+biology(?:\s+(.+))?$/i);
if(!m){skip=true;}else{
 const q=String(m[1]||'').trim(),D=storage.sys_lc_biology_definitions??{},P=storage.sys_lc_biology_profiles??{};
 let text='';
 if(!q)text='LC Biology: '+Object.keys(D).length+' definitions, '+Object.keys(P).length+' individual profiles. Schema v'+String(storage.sys_lc_biology_schema_version??1)+'.';
 else{
  const key=Object.keys(P).find(k=>k.toLowerCase()===q.toLowerCase())??Object.keys(D).find(k=>k.toLowerCase()===q.toLowerCase());
  const x=P[key]??D[key];text=x?'LC Biology '+key+': '+JSON.stringify(x):'LC Biology: no registered definition/profile named "'+q+'".';
 }
 effects.push({type:'story',instruction:'OUT-OF-WORLD LC BIOLOGY STATUS. Do not advance time or treat as character speech. '+text.slice(0,3000)});
}

